import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"The Fable Loop Library: 25 Workflows on Autopilot","description":"","frontmatter":{"url":"https://x.com/EXM7777/status/2073432521954697653","title":"The Fable Loop Library: 25 Workflows on Autopilot","author":"Machina","archived":"2026-07-06T00:00:00.000Z","handle":"@EXM7777","published":"2026-07-04T00:00:00.000Z","stats":"857 likes · 84 retweets · 2767 bookmarks · 484770 views","tags":["agentic-loop","fable-5","workflow","mcp-tools","loop-engineering","cheap-routing"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-04-@EXM7777-697653.md","filePath":"research/tweets/2026-07-04-@EXM7777-697653.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-07-04-@EXM7777-697653.md"};function i(n,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="the-fable-loop-library-25-workflows-on-autopilot-—-exm7777" tabindex="-1">The Fable Loop Library: 25 Workflows on Autopilot — @EXM7777 <a class="header-anchor" href="#the-fable-loop-library-25-workflows-on-autopilot-—-exm7777" aria-label="Permalink to &quot;The Fable Loop Library: 25 Workflows on Autopilot — @EXM7777&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/EXM7777/status/2073432521954697653" target="_blank" rel="noreferrer">https://x.com/EXM7777/status/2073432521954697653</a><strong>作者</strong>：Machina（@EXM7777） <strong>發布日期</strong>：2026-07-04 <strong>收錄日期</strong>：2026-07-06 <strong>類型</strong>：Twitter Article <strong>統計</strong>：857 likes · 84 retweets · 2767 bookmarks · 484770 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>i&#39;m going to teach you how to run Fable 5 on autopilot, using my own library of loops and goals... 25 workflows, each with a prompt and the exact tool it plugs into the method follows karpathy&#39;s recipe for agents: &quot;here&#39;s an objective, here&#39;s a metric, here&#39;s your boundaries of what you can and cannot do. And go&quot; every workflow below is exactly that... an objective, boundaries, and the proof it&#39;s done Fable 5 is the model built for this: it holds one job for hours without losing the plot, where other models wander off after minutes remember these two Claude Code commands:</p><blockquote><p>/loop - a job that repeats on a schedule until it&#39;s done /goal - a finish line you write once, and the model works alone until it&#39;s crossed one warning before you schedule anything: a model that never gets tired never stops on its own, and Fable is the most expensive model on the market run it without a budget and a stop rule and the bill will find you... every workflow below carries both the ready-to-run versions of these loops, and the training on turning them into income, live in the real time AI ops community: weeklyaiops.com</p></blockquote><h1 id="what-s-a-loop" tabindex="-1">what&#39;s a loop? <a class="header-anchor" href="#what-s-a-loop" aria-label="Permalink to &quot;what&#39;s a loop?&quot;">​</a></h1><p>a loop is a job your agent repeats on a schedule: every morning, or every time something new lands five parts, always:</p><blockquote><p>a schedule - when it wakes up ONE change per round - it fixes the single most important thing it found, never everything at once the same check every time - so this week&#39;s score can be compared against last week&#39;s a state file - a text file where it writes what it did and what&#39;s queued next a stop - a hard cap on rounds and a rule for what &quot;done&quot; and &quot;blocked&quot; look like it&#39;s the same shape frontier researchers run their own experiments on: change one thing, test it, keep it only if it improved, write it down, repeat the state file is the part almost everyone skips, and it&#39;s the part that makes every run smarter than the last the model reads its own history before every round, so it never redoes finished work every loop below also carries a color: green - safe to run alone: it only reads things and writes to its own files yellow - it drafts, you approve: replies, page edits, PRs, anything a human ships red - never runs alone: money, production, outbound messages, or anything a customer sees run any loop once by hand before you schedule it and route it cheap: a smaller model runs the routine rounds, Fable steps in only where the cheap model failed</p></blockquote><h1 id="what-s-a-goal" tabindex="-1">what&#39;s a goal? <a class="header-anchor" href="#what-s-a-goal" aria-label="Permalink to &quot;what&#39;s a goal?&quot;">​</a></h1><p>a goal is the other shape of work: not a schedule, a finish line you type /goal, describe what done looks like, and the model keeps working on its own... a second, smaller model reads along as the judge and confirms when the line is crossed one detail decides whether this is useful or a token bonfire: the judge only sees the conversation it can&#39;t open your files, can&#39;t run your tests, can&#39;t check your site so &quot;done when the tests pass&quot; is a wish... &quot;done when the full green test run is PASTED in the chat&quot; is a contract agents say &quot;done&quot; all the time without it being true... proof you can read is the only version that counts every goal below ends the same way: paste the proof, and if you can&#39;t, paste the failures and stop</p><h1 id="the-library" tabindex="-1">the library <a class="header-anchor" href="#the-library" aria-label="Permalink to &quot;the library&quot;">​</a></h1><p>how to read each entry: the name, the tool it plugs into, why it earns a slot... and the full working prompt, ready for your terminal two words you&#39;ll see:</p><blockquote><p>MCP - a plug that gives your agent direct access to an app (your inbox, your analytics, your repo, your ad account) API key - a password that lets the agent read a service on your behalf the tools named per loop were researched for agent access specifically... hosted MCPs with OAuth where they exist, cheap pay-as-you-go APIs where they don&#39;t paste each prompt into Claude Code, set the cadence line as your schedule, and swap the bracketed parts for your business</p></blockquote><h2 id="marketing-content" tabindex="-1">marketing + content <a class="header-anchor" href="#marketing-content" aria-label="Permalink to &quot;marketing + content&quot;">​</a></h2><ol><li>answer-engine gap loop · Exa MCP your buyers ask ChatGPT and Perplexity questions your site should be the answer to, and every unanswered one is a competitor&#39;s citation this loop finds the gaps and closes exactly one per week [圖 1]</li><li>programmatic-page quality gate · Search Console MCP if you generate pages from a template, thin and duplicate pages leak into google&#39;s index and drag the whole site down the gate catches the worst pattern before google does [圖 2]</li><li>share-of-model brand watch · Perplexity API key when buyers ask AI engines &quot;best [your category]&quot;, you&#39;re either in the answer or invisible every week it asks the same questions and logs where you stand, so you see the trend instead of guessing [圖 3]</li><li>competitor-content watch loop · DataForSEO MCP + Firecrawl monitor your competitors tell you their SEO strategy every week... in the articles they publish and the keywords those articles chase reading both and planning your next moves against their gaps is a friday job... this is the friday job [圖 4]</li><li>content-brief backlog loop · Search Console MCP the writing pipeline dies at the blank page, not at the writing the backlog stays stocked with fully specified briefs mined from your own traffic and questions [圖 5]</li><li>X content-idea miner · twitterapi.io + Typefully the accounts you respect are running your content R&amp;D for free... every high-performing post in your niche is a proven angle waiting for your version a watched list, a ranking of what&#39;s working, and your take drafted in your own voice, every morning [圖 6]</li><li>ad-creative fatigue drafting loop · Meta Marketing API ad sets decay, and the usual response is noticing two weeks late the next batch sits drafted before the drop, grounded in what already won for you... and nothing launches without you [圖 7]</li><li>expectation-gap audit · Zendesk MCP when a customer writes &quot;i thought it did X&quot;, a page somewhere promised them X this audit starts from the disappointment and walks backwards to the sentence that caused it [圖 8]</li><li>presale questions loop the questions people ask BEFORE buying are answers you keep retyping they&#39;re already sitting in your DMs, comments and emails... this loop turns them into an answer bank you never write twice marketing finds the demand... product decides what gets built next [圖 9]</li></ol><h2 id="product" tabindex="-1">product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;product&quot;">​</a></h2><ol start="10"><li>brand-mention feature radar · Reddit API + HN Algolia + Exa people tell the internet what they wish your product did, they just never tell you the mentions get swept weekly, the complaints and feature asks clustered, and the loudest one arrives as a drafted implementation plan [圖 10]</li><li>review-mine to roadmap · app store review APIs your customers write your roadmap every week in reviews and support messages... in their words, ranked by pain it just needs compiling [圖 11]</li><li>drop-point copy loop · PostHog MCP somewhere in your product, users hit a moment that makes them give up... and the words on that screen are usually half the reason analytics finds the moment, this loop fixes the words product listens... operations answers [圖 12]</li></ol><h2 id="business-ops" tabindex="-1">business ops <a class="header-anchor" href="#business-ops" aria-label="Permalink to &quot;business ops&quot;">​</a></h2><ol start="13"><li>inbox-to-decision triage loop · Gmail MCP a shared inbox is a decision queue wearing a disguise every unread item becomes decide / delegate / defer / drop, with the top reply already drafted [圖 13]</li><li>month-close reconciliation prep · QuickBooks API the boring half of closing the books is categorizing transactions against your own history this loop does the boring half and hands a human a short exception list... it never files anything [圖 14]</li><li>SOP-drift catcher · Notion MCP the written process and the real process drift apart in silence, and the doc is always the last to know comparing how work actually happened against the SOP is a job, and this one does it weekly [圖 15]</li><li>proposal / RFP backlog drafter every RFP asks 80% questions you&#39;ve answered before and 20% that are genuinely new this loop drafts the 80 from your answer library and flags the 20, so proposals move daily instead of stalling [圖 16]</li><li>KPI anomaly watch · PostHog MCP + Stripe dashboards show everything, which is why nobody looks silent on normal days, and when a metric breaks its band you get paged with the likely cause pre-investigated [圖 17]</li><li>unpaid-invoice chaser · Stripe API key b2b clients pay late because late payment usually costs them nothing this loop keeps an aging ledger and drafts the next nudge at each threshold... you send, it remembers operations keeps the machine running... research decides where it points next [圖 18]</li></ol><h2 id="research-decisions" tabindex="-1">research + decisions <a class="header-anchor" href="#research-decisions" aria-label="Permalink to &quot;research + decisions&quot;">​</a></h2><ol start="19"><li>overnight intel refresh · Exa MCP + Firecrawl monitor markets move weekly whether you&#39;re watching or not a cheap model watches your tracked sources on schedule, and the big model only writes the monthly synthesis [圖 19]</li><li>regulatory / source digest · Firecrawl MCP some sources you can&#39;t afford to skim: the regulators and the two papers that will change your niche only what materially changed gets digested, with a plain-language &quot;so what&quot; [圖 20]</li><li>hard-question escalation queue paying flagship prices for questions a cheap model answers is the default way agent bills explode this queue makes every question earn its escalation: cheap model first, Fable only on a logged failure [圖 21]</li><li>kill-criteria loop options survive meetings because nobody wrote down what would disqualify them here every live option declares its kill condition upfront... then the evidence hunt begins [圖 22]</li><li>pre-mortem loop it&#39;s 12 months from now and the decision failed... writing that story before you commit is the cheapest insurance there is [圖 23]</li><li>repeat-offender digest the same failure showing up in two different workflows is not two bugs... it&#39;s one system problem wearing two costumes this digest reads every run ledger and hunts the costume changes [圖 24]</li><li>shadow prompt loop testing a new prompt on hand-picked examples tells you it passed your imagination, nothing more run it in the shadows against real traffic and let the disagreements decide and if your business ships software, the next thirteen live inside your repo and your CI... the system that auto-runs your tests on every change [圖 25]</li></ol><h1 id="start-here" tabindex="-1">start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;start here&quot;">​</a></h1><p>the whole system, in order... copy this:</p><blockquote><p>pick ONE loop that touches your biggest leak: inbox, KPIs, content, errors run it once by hand and read the state file it writes schedule it, with the cadence line as written after a week, add a second loop or hand a cursed one-shot to a /goal with pasted-proof done conditions route cheap: a smaller model runs the routine rounds, Fable takes what the cheap model failed money, production and outbound messages always end at a human... the prompts are built that way, keep it that way one more thing on cost: Fable 5 comes off subscription plans on july 7 and moves to pay-as-you-go credits after that date the cheap-first routing and the hard caps in these prompts stop being style and start being the bill that endurance is sitting in your terminal right now these 25 give it a job and a finish line the smallest start is one loop and one state file the rest schedules itself join the best AI community in the world: weeklyaiops.com (part 2 coming soon with 25 new workflows...)</p></blockquote><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Loop = schedule+ONE-change+state-file+stop-rule；Goal = verifiable proof in chat；25 個 Fable 5 agentic workflow 涵蓋 marketing/product/ops/research 四大場景。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>Loop 五部分</strong>（schedule / ONE change per round / same check every time / state file / stop rule）與 Karpathy recipe 完全對齊；state file 是被忽略最多但讓每 round 更聰明的關鍵（每輪開始前讀自己歷史）</li><li><strong>Goal contract</strong>：「done when tests pass」是願望；「done when full green test run is PASTED in chat」才是合約 — 與 cc-workspace Done Contract 原則高度一致</li><li><strong>安全分級三色</strong>：green（只讀自己檔案，可全自主）/ yellow（草稿+人工核可，涉及對外輸出）/ red（永遠不自動：金錢、生產、客戶可見訊息）</li><li><strong>Cheap-first routing</strong>：便宜模型跑例行 round，Fable 只在便宜模型失敗時介入 — 直接對應 subagent-strategy.md 的 benefit-gated 委派原則</li><li><strong>Fable 5 PAYG 轉換</strong>：2026-07-07 起離開訂閱制改 pay-as-you-go；strong budget cap + stop rule 從風格選擇變成帳單必要條件</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>25 個 workflow，分 marketing(9) / product(3) / business ops(6) / research &amp; decisions(7) 四大類</li><li>Fable 5：2026-07-07 移出訂閱計畫，改 PAYG credits</li><li>MCP 工具清單：Exa MCP、Search Console MCP、PostHog MCP、Gmail MCP、Notion MCP、DataForSEO MCP、Firecrawl MCP、Zendesk MCP</li><li>API key 工具：Perplexity API、Meta Marketing API、Stripe API、QuickBooks API、Reddit API、HN Algolia、twitterapi.io、Typefully</li><li>社群資源：weeklyaiops.com（付費，完整 prompt 庫在此）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>Prompt 封鎖</strong>：25 個 workflow 的實際 prompt 藏在圖片中（fxtwitter 不回傳圖片 URL），文章核心可行動價值被 paywall 隔離；本文只提供概念框架和工具選型，非完整操作手冊</li><li><strong>促銷導向</strong>：weeklyaiops.com community 多次出現，「ready-to-run versions」和「training」皆指向付費牆後，降低了內容的自足性</li><li><strong>部分原則已在 cc-workspace</strong>：cheap-first routing 已在 subagent-strategy.md；Done Contract 已在 core.md；state file 概念是新洞見，可補充到 core.md RECORD 階段或 /loop skill</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>6/10</td><td>Loop 框架和 cheap-first routing 可直接參照，但 25 個具體 prompt 藏圖中無法複用</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>state file 的強調和三色安全分級有新洞見；cheap-first routing 與現有規則呼應但角度清晰</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>無具體 benchmark 數據，多為描述性斷言，符合 Twitter Article ≤ 6 上限</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>MCP 工具選型理由具體（OAuth-first / PAYG API），loop 五部分框架可直接實作</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>loop+goal 架構跨業務場景高度通用；四大領域覆蓋面廣</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.5/10</strong></td><td>6×0.3+7×0.2+5×0.2+7×0.15+8×0.15 = 1.8+1.4+1.0+1.05+1.2</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：state file 強制執行 + 三色安全分級 + proof-in-chat goal 契約可補充進 core.md RECORD 與 /loop skill；cheap-first routing 強化現有 subagent-strategy.md</p>',38)])])}const g=t(s,[["render",i]]);export{p as __pageData,g as default};
